template.query:
mutation CreateRelationBetweenNodes($tableId: ID!, $sourceNodeId: ID!, $targetNodeId: ID!, $relationTypeId: ID!) {
  createRelation(
    input: {
      tableId: $tableId
      sourceNodeId: $sourceNodeId
      targetNodeId: $targetNodeId
      relationTypeId: $relationTypeId
    }
  ) {
    success
    relation {
      id
      table {
        id
        identifier
      }
      sourceNode {
        id
        content
      }
      targetNode {
        id
        content
      }
      relationType {
        id
        identifier
        name
        description
      }
      createdAt
      updatedAt
    }
    errors {
      message
      code
      field
    }
  }
}
